package org.springframework.samples.petclinic.rest.advice;

import java.util.List;

/**
 * Thrown when a request to create or update an owner supplies a mandatory field that is present
 * but fails a business rule on its value (for example a telephone that is not exactly ten digits
 * after non-digit characters are stripped). The {@link #getInvalidFields()} list carries the names
 * of the offending fields so the response can report exactly which values were rejected.
 */
public class InvalidOwnerFieldsException extends RuntimeException {

    private final List<String> invalidFields;

    public InvalidOwnerFieldsException(List<String> invalidFields) {
        super("Invalid owner fields: " + invalidFields);
        this.invalidFields = List.copyOf(invalidFields);
    }

    public List<String> getInvalidFields() {
        return this.invalidFields;
    }
}

