151	        validateRequiredOwnerFields(ownerFieldsDto);
152	        LocalDate suppliedOrDefaultDate =
153	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
154	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
155	        rejectDailyLimitExceeded(registrationDate);
