267	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
268	            }
269	        }
270	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	    }
272	
273	    /**
274	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
275	     * offending field is collected so the caller learns exactly which values must be supplied.
276	     *
277	     * @param ownerFieldsDto the submitted owner payload
278	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
279	     *         telephone is missing or blank
280	     */
281	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
282	        List<String> missingFields = new ArrayList<>();
283	        if (isBlank(ownerFieldsDto.getFirstName())) {
284	            missingFields.add("firstName");
285	        }
286	        if (isBlank(ownerFieldsDto.getLastName())) {
287	            missingFields.add("lastName");
288	        }
289	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
290	            missingFields.add("address");
291	        }
292	        if (isBlank(ownerFieldsDto.getCity())) {
293	            missingFields.add("city");
294	        }
295	        if (isBlank(ownerFieldsDto.getTelephone())) {
296	            missingFields.add("telephone");
297	        }
298	        if (!missingFields.isEmpty()) {
299	            throw new MissingOwnerFieldsException(missingFields);
300	        }
301	    }
302	
303	    private boolean isBlank(String value) {
304	        return value == null || value.isBlank();
305	    }
306	
307	    /**
308	     * Counts the existing owners who, before this create, already share the given first and last name.
309	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
310	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
311	     * case or spacing still count as the same name.
312	     *
313	     * @param firstName the first name of the owner being created
314	     * @param lastName the last name of the owner being created
315	     * @return the number of existing owners sharing both names (zero when none)
316	     */
317	    private int countNamesakes(String firstName, String lastName) {
318	        String first = normalizeHouseholdField(firstName);
319	        String last = normalizeHouseholdField(lastName);
320	        return (int) this.clinicService.findAllOwners().stream()
321	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
322	                && normalizeHouseholdField(existing.getLastName()).equals(last))
323	            .count();
324	    }
325	
326	    /**
327	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
328	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
329	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
330	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
331	     * more owners the create is rejected as a conflict.
332	     *
333	     * @param city the city of the owner being created
334	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
335	     */
336	    /**
337	     * Rejects an owner create once the maximum number of owners have already been registered on the
338	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
339	     * which is always a business day (a weekend effective date is rolled forward to the following
340	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
341	     * business day the create is rejected as too many requests. Because a weekend effective date is
342	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
343	     *
344	     * @param businessDay the adjusted business day the owner being created would be registered on
345	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
346	     */
347	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
348	        long ownersOnDay = this.clinicService.findAllOwners().stream()
349	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
350	            .count();
351	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
352	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
353	        }
354	    }
355	
356	    /**
357	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
358	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
359	     * was supplied on the request or defaulted to the server's current date.
360	     *
361	     * @param date the effective registration date (supplied or defaulted)
362	     * @return the same date when it is a weekday, otherwise the following Monday
363	     */
364	    /**
365	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
366	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
367	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
368	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
369	     *
370	     * @return {@code true} when more than the threshold number of owners are already registered on
371	     *         today's business day, otherwise {@code false}
372	     */
373	    private boolean isBulkSignupWarningActive() {
374	        LocalDate today = toBusinessDay(LocalDate.now());
375	        long ownersToday = this.clinicService.findAllOwners().stream()
376	            .filter(existing -> today.equals(existing.getRegistrationDate()))
377	            .count();
378	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
379	    }
380	
381	    private LocalDate toBusinessDay(LocalDate date) {
382	        return switch (date.getDayOfWeek()) {
383	            case SATURDAY -> date.plusDays(2);
384	            case SUNDAY -> date.plusDays(1);
385	            default -> date;
386	        };
387	    }
388	
389	    private void rejectCityAtCapacity(String city) {
390	        String normalizedCity = normalizeHouseholdField(city);
391	        long ownersInCity = this.clinicService.findAllOwners().stream()
392	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
393	            .count();
394	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
395	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
396	        }
397	    }
398	
399	    /**
400	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
401	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
402	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
403	     * of owners already in that city (e.g. 'SYD-SMI-0007').
404	     *
405	     * @param city the owner's city
406	     * @param lastName the owner's last name
407	     * @return the formatted customer code
408	     */
409	    private String generateCustomerCode(String city, String lastName) {
410	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
411	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
412	        String normalizedCity = normalizeHouseholdField(city);
413	        int sequence = (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
415	            .count() + 1;
416	        return String.format("%s-%s-%04d", city3, last3, sequence);
417	    }
418	
419	    /**
420	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
421	     * customerCode is the owner's customer code and YY is the last two digits of the
422	     * registrationDate year (e.g. 'SMI-0007-M26').
423	     *
424	     * @param customerCode the owner's customer code
425	     * @param registrationDate the owner's registration date
426	     * @return the formatted membership number
427	     */
428	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
429	        String yy = String.format("%02d", registrationDate.getYear() % 100);
430	        return customerCode + "-M" + yy;
431	    }
432	
433	    /**
434	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
435	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
436	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
437	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
438	     * stored and returned.
439	     *
440	     * @param telephone the raw telephone value from the request
441	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
442	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
443	     */
444	    private String normalizeTelephone(String telephone) {
445	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
446	        String e164;
447	        if (cleaned.startsWith("+")) {
448	            e164 = cleaned;
449	        } else {
450	            String national = cleaned;
451	            if (national.startsWith("0")) {
452	                national = national.substring(1);
453	            }
454	            e164 = "+61" + national;
455	        }
456	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
457	            throw new InvalidOwnerFieldsException(List.of("telephone"));
458	        }
459	        return e164;
460	    }
461	
462	    /**
463	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
464	     * left unset. When a value is present it must be a syntactically valid address; the normalized
465	     * form stored and returned is the value lower-cased.
466	     *
467	     * @param email the raw email value from the request, or {@code null} when none was supplied
468	     * @return the lower-cased email, or {@code null} when no email was supplied
469	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
470	     */
471	    private String normalizeEmail(String email) {
472	        if (email == null || email.isBlank()) {
473	            return null;
474	        }
475	        if (!EMAIL_PATTERN.matcher(email).matches()) {
476	            throw new InvalidOwnerFieldsException(List.of("email"));
477	        }
478	        return email.toLowerCase(Locale.ROOT);
479	    }
480	
481	    /**
482	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
483	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
484	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
485	     * normalized form is what gets stored, returned and used for every address comparison (the
486	     * required-field check, household duplicate detection and the shared household id).
487	     *
488	     * @param address the raw address value from the request, or {@code null}
489	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
490	     */
491	    private String normalizeAddress(String address) {
492	        if (address == null) {
493	            return "";
494	        }
495	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
496	        if (collapsed.isEmpty()) {
497	            return "";
498	        }
499	        String[] tokens = collapsed.split(" ");
500	        for (int i = 0; i < tokens.length; i++) {
501	            switch (tokens[i]) {
502	                case "ST" -> tokens[i] = "STREET";
503	                case "RD" -> tokens[i] = "ROAD";
504	                case "AVE" -> tokens[i] = "AVENUE";
505	                default -> { }
506	            }
507	        }
508	        return String.join(" ", tokens);
509	    }
510	
511	    /**
512	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
513	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
514	     * directly and is therefore independent of the punctuation a caller supplied.
515	     *
516	     * @param e164Telephone the E.164 telephone of the owner being created
517	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
518	     */
519	    private void rejectDuplicateTelephone(String e164Telephone) {
520	        boolean inUse = this.clinicService.findAllOwners().stream()
521	            .map(Owner::getTelephone)
522	            .filter(existing -> existing != null)
523	            .anyMatch(e164Telephone::equals);
524	        if (inUse) {
525	            throw new DuplicateOwnerTelephoneException(e164Telephone);
526	        }
527	    }
528	
529	    /**
530	     * Rejects an owner create whose lower-cased email is already used by any other owner. Owners
531	     * store their email in lower-cased form, so the uniqueness check compares these canonical values
532	     * directly and is therefore independent of the letter case a caller supplied. An owner with no
533	     * email supplied ({@code null}) is not subject to this check, since there is no value to collide.
534	     *
535	     * @param email the lower-cased email of the owner being created, or {@code null} when none was supplied
536	     * @throws DuplicateOwnerEmailException if another owner already uses this email
537	     */
538	    private void rejectDuplicateEmail(String email) {
539	        if (email == null) {
540	            return;
541	        }
542	        boolean inUse = this.clinicService.findAllOwners().stream()
543	            .map(Owner::getEmail)
544	            .filter(existing -> existing != null)
545	            .anyMatch(email::equalsIgnoreCase);
546	        if (inUse) {
547	            throw new DuplicateOwnerEmailException(email);
548	        }
549	    }
550	
551	    /**
552	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
553	     * last name and a normalized address: last names are compared case-insensitively after whitespace
554	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
555	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
556	     * abbreviation still count as the same household.
557	     * <p>
558	     * When the owner's last name and address already belong to at least one other owner the behaviour
559	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
560	     * household. If it is true the create is allowed and every member of the household - the existing
561	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
562	     * read. When no other owner shares the last name and address no identifier is assigned.
563	     *
564	     * @param owner the owner being created
565	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
566	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
567	     *         address and {@code sharesHousehold} is not true
568	     */
569	    /**
570	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
571	     * household member count} for the response.
572	     *
573	     * @param owner the owner to map
574	     * @return the mapped owner DTO
575	     */
576	    private OwnerDto toOwnerDto(Owner owner) {
577	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
578	        return ownerMapper.toOwnerDto(owner);
579	    }
580	
581	    /**
582	     * Counts the members of the given owner's household - the owners that share this owner's
583	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
584	     * is {@code null}) is its own sole member, so the count is one.
585	     *
586	     * @param owner the owner whose household is being sized
587	     * @return the number of owners sharing this owner's household (one when it has no household)
588	     */
589	    private int countHouseholdMembers(Owner owner) {
590	        String householdId = owner.getHouseholdId();
591	        if (householdId == null) {
592	            return 1;
593	        }
594	        return (int) this.clinicService.findAllOwners().stream()
595	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
596	            .count();
597	    }
598	
599	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
600	        String lastName = normalizeHouseholdField(owner.getLastName());
601	        String address = normalizeAddress(owner.getAddress());
602	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
603	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
604	                && normalizeAddress(existing.getAddress()).equals(address))
605	            .toList();
606	        if (housemates.isEmpty()) {
607	            return;
608	        }
609	        if (!Boolean.TRUE.equals(sharesHousehold)) {
610	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
611	        }
612	        String householdId = generateHouseholdId(lastName, address);
613	        owner.setHouseholdId(householdId);
614	        for (Owner housemate : housemates) {
615	            if (!householdId.equals(housemate.getHouseholdId())) {
616	                housemate.setHouseholdId(householdId);
617	                this.clinicService.saveOwner(housemate);
618	            }
619	        }
620	    }
621	
622	    /**
623	     * Builds the stable identifier shared by the members of one household. It is derived purely from
624	     * the normalized last name and address, so every owner of a given household deterministically
625	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
626	     * two normalized fields joined by a single space.
627	     *
628	     * @param normalizedLastName the household's last name, already normalized for comparison
629	     * @param normalizedAddress the household's address, already normalized for comparison
630	     * @return the shared household identifier
631	     */
632	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
633	        String key = normalizedLastName + '�' + normalizedAddress;
634	        try {
635	            byte[] digest = MessageDigest.getInstance("SHA-256")
636	                .digest(key.getBytes(StandardCharsets.UTF_8));
637	            StringBuilder hex = new StringBuilder();
638	            for (byte b : digest) {
639	                hex.append(String.format("%02X", b));
640	                if (hex.length() >= 12) {
641	                    break;
642	                }
643	            }
644	            return hex.substring(0, 12);
645	        } catch (NoSuchAlgorithmException e) {
646	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
647	        }
648	    }
649	
650	    /**
651	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
652	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
653	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
654	     * expands common abbreviations.
655	     *
656	     * @param value the raw last name, or {@code null}
657	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
658	     */
659	    private String normalizeHouseholdField(String value) {
660	        if (value == null) {
661	            return "";
662	        }
663	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
664	    }
665	}
